"use client";
import {useEffect} from "react";
import Lenis from "lenis";
import {AnimatePresence,motion} from "motion/react";
import {acts,systemDetails} from "@/lib/story";
import {useArchive} from "@/store/archive";

export function ArchiveOverlay(){
  const act=useArchive(s=>s.act);
  const setMotion=useArchive(s=>s.setMotion);
  const selected=useArchive(s=>s.selected);
  const select=useArchive(s=>s.select);
  const current=acts[act]??acts[0];
  const selectedDetail=selected?systemDetails[selected]:null;

  useEffect(()=>{
    const lenis=new Lenis({duration:1.08,smoothWheel:true,wheelMultiplier:.92,touchMultiplier:1});
    lenis.on("scroll",({progress,velocity}:{progress:number;velocity:number})=>setMotion(progress,velocity));
    let frame=0;const raf=(time:number)=>{lenis.raf(time);frame=requestAnimationFrame(raf)};frame=requestAnimationFrame(raf);
    return()=>{cancelAnimationFrame(frame);lenis.destroy();};
  },[setMotion]);

  return <>
    <header className="topbar">
      <a className="brand" href="#archive"><span>MP</span><b>THE ARCHIVE</b></a>
      <div className="year">{current.year}</div>
      <nav><a href="https://github.com/maharshimak">GitHub</a><a href="https://www.linkedin.com/in/maharshi-patel-6bb638298/">LinkedIn</a></nav>
    </header>

    <section id="archive" className="scroll-track" aria-label="Interactive career archive">
      {acts.map(a=><article key={a.id} className="scroll-act" aria-label={a.title}/>)}
    </section>

    <div className="rail" aria-hidden="true">
      {acts.map((a,index)=><span key={a.id} className={index===act?"active":""}><i/>{a.year}</span>)}
    </div>

    <AnimatePresence mode="wait">
      <motion.aside
        key={current.id}
        className="story-copy"
        initial={{opacity:0,y:24,filter:"blur(8px)"}}
        animate={{opacity:1,y:0,filter:"blur(0px)"}}
        exit={{opacity:0,y:-14,filter:"blur(5px)"}}
        transition={{duration:.55,ease:[.2,.8,.2,1]}}
      >
        <p>{current.kicker}</p>
        <h1>{current.title}</h1>
        <h2>{current.subtitle}</h2>
        <div className="rule"/>
        <p className="body">{current.body}</p>
      </motion.aside>
    </AnimatePresence>

    <footer className="hint">{act===0?"SCROLL TO ENTER":"SCROLL = TIME · MOVE POINTER = LOOK"}</footer>

    <AnimatePresence>
      {selected?<motion.div className="inspector" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}>
        <motion.div className="inspector-panel" initial={{y:30,scale:.98}} animate={{y:0,scale:1}} exit={{y:20,scale:.985}}>
          <button onClick={()=>select(null)}>← RETURN</button>
          <p>MAK&apos;MA SYSTEM</p><h3>{selected}</h3>
          <p>{selectedDetail?.summary??"A connected system inside the MAK'MA engineering archive."}</p>
          {selectedDetail?<a className="repo-link" href={`https://github.com/maharshimak/${selectedDetail.slug}`}>OPEN REPOSITORY ↗</a>:null}
        </motion.div>
      </motion.div>:null}
    </AnimatePresence>
  </>;
}

