function useArchiveMaterials(){
  const [floor,floorNormal,floorRough,door,doorNormal,doorRough]=useTexture([
    assetPath("/assets/materials/hangar_concrete_floor/diffuse.jpg"),
    assetPath("/assets/materials/hangar_concrete_floor/normal.jpg"),
    assetPath("/assets/materials/hangar_concrete_floor/roughness.jpg"),
    assetPath("/assets/materials/rough_pine_door/diffuse.jpg"),
    assetPath("/assets/materials/rough_pine_door/normal.jpg"),
    assetPath("/assets/materials/rough_pine_door/roughness.jpg")
  ]);
  floor.colorSpace=door.colorSpace=SRGBColorSpace;
  for(const texture of [floor,floorNormal,floorRough]){
    texture.wrapS=texture.wrapT=RepeatWrapping;
    texture.repeat.set(3,24);
  }
  for(const texture of [door,doorNormal,doorRough]){
    texture.wrapS=texture.wrapT=RepeatWrapping;
    texture.repeat.set(1.2,1.5);
  }
  return {floor,floorNormal,floorRough,door,doorNormal,doorRough};
}

