import {mkdir,writeFile} from "node:fs/promises";
import {dirname,join} from "node:path";

const OUT="public/assets";
const UA="MaharshiArchiveV4/1.0";
const POLY="https://api.polyhaven.com";
const TEMPLATE_COMMIT="edc716e10c120f5e19aa8358be433222a83d453e";
const TEMPLATE_BASE=`https://raw.githubusercontent.com/mohitvirli/mohitvirli.github.io/${TEMPLATE_COMMIT}/public/models`;

async function download(url,destination){
  await mkdir(dirname(destination),{recursive:true});
  const response=await fetch(url,{headers:{"User-Agent":UA}});
  if(!response.ok) throw new Error(`download ${response.status}: ${url}`);
  const buffer=Buffer.from(await response.arrayBuffer());
  await writeFile(destination,buffer);
  console.log(`saved ${destination} ${(buffer.length/1024/1024).toFixed(2)}MB`);
}

function flatten(value,path=[],out=[]){
  if(typeof value==="string"&&/^https?:\/\//.test(value)) out.push({path:path.join("/").toLowerCase(),url:value});
  else if(Array.isArray(value)) value.forEach((item,index)=>flatten(item,[...path,String(index)],out));
  else if(value&&typeof value==="object"){
    if(typeof value.url==="string") out.push({path:path.join("/").toLowerCase(),url:value.url});
    for(const [key,item] of Object.entries(value)) flatten(item,[...path,key],out);
  }
  return out;
}
function choose(candidates,terms,exts){
  return candidates
    .filter((item)=>exts.some((ext)=>item.url.toLowerCase().includes(ext)))
    .map((item)=>{
      const hay=(item.path+" "+item.url).toLowerCase();
      let score=0;
      for(const [i,term] of terms.entries()) if(hay.includes(term)) score+=100-i*6;
      if(hay.includes("1k")) score+=60;
      if(hay.includes("2k")) score+=18;
      if(hay.includes("4k")) score-=20;
      return {...item,score};
    })
    .sort((a,b)=>b.score-a.score)[0];
}
async function polyFiles(id){
  const response=await fetch(`${POLY}/files/${id}`,{headers:{"User-Agent":UA}});
  if(!response.ok) throw new Error(`Poly Haven ${response.status}: ${id}`);
  return response.json();
}
async function fetchHdri(id){
  const candidates=flatten(await polyFiles(id));
  const selected=choose(candidates,["1k","hdr"],[".hdr"]);
  if(!selected) throw new Error(`HDR missing: ${id}`);
  await download(selected.url,join(OUT,"hdri",`${id}_1k.hdr`));
}
async function fetchMaterial(id){
  const candidates=flatten(await polyFiles(id));
  const defs=[
    ["diffuse",["diff","basecolor"]],
    ["normal",["nor_gl","normal"]],
    ["roughness",["rough","roughness"]]
  ];
  for(const [name,terms] of defs){
    const selected=choose(candidates,terms,[".jpg",".png",".webp"]);
    if(!selected) continue;
    const ext=selected.url.match(/\.(jpg|png|webp)(?:\?|$)/i)?.[1]??"jpg";
    await download(selected.url,join(OUT,"materials",id,`${name}.${ext}`));
  }
}

await Promise.all([
  fetchHdri("museum_of_ethnography"),
  fetchHdri("st_fagans_interior"),
  fetchHdri("university_workshop"),
  fetchMaterial("hangar_concrete_floor"),
  fetchMaterial("rough_pine_door")
]);

await Promise.all([
  download(`${TEMPLATE_BASE}/window.glb`,join(OUT,"models","window.glb")),
  download(`${TEMPLATE_BASE}/wanderer_above_the_sea_of_fog.glb`,join(OUT,"models","wanderer.glb")),
  download(`${TEMPLATE_BASE}/dalithe_persistence_of_memory.glb`,join(OUT,"models","memory.glb"))
]);

await writeFile(join(OUT,"CREDITS.json"),JSON.stringify({
  generated:new Date().toISOString(),
  assets:[
    {title:"Museum of Ethnography",source:"https://polyhaven.com/a/museum_of_ethnography",license:"CC0",author:"Oliksiy Yakovlyev"},
    {title:"St. Fagans Interior",source:"https://polyhaven.com/a/st_fagans_interior",license:"CC0",author:"Morgan Evans"},
    {title:"University Workshop",source:"https://polyhaven.com/a/university_workshop",license:"CC0",author:"Savva Zakharov"},
    {title:"Hangar Concrete Floor",source:"https://polyhaven.com/a/hangar_concrete_floor",license:"CC0",author:"Dimitrios Savva"},
    {title:"Rough Pine Door",source:"https://polyhaven.com/a/rough_pine_door",license:"CC0",author:"Dimitrios Savva"},
    {title:"Residential Window",source:"https://sketchfab.com/3d-models/residential-window-ae11104237314463a61251fd46ded4b4",license:"CC-BY-4.0",author:"AleixoAlonso"},
    {title:"Wanderer above the sea of fog",source:"https://sketchfab.com/3d-models/wanderer-above-the-sea-of-fog-518e605e9b734c86aab5bc22f9797f77",license:"CC-BY-SA-4.0",author:"betocarrillo"},
    {title:"Dali, The Persistence of Memory",source:"https://sketchfab.com/3d-models/dalithe-persistence-of-memory-ab3e99facbdb4d9d8661d3f07815638e",license:"CC-BY-4.0",author:"arloopa"}
  ]
},null,2));
console.log("Archive assets ready.");

