import {chromium} from "@playwright/test";
import {mkdir} from "node:fs/promises";

await mkdir("visual-review",{recursive:true});
const browser=await chromium.launch({headless:true});
const context=await browser.newContext({viewport:{width:1440,height:900},deviceScaleFactor:1});
const page=await context.newPage();
await page.goto("http://127.0.0.1:4175/",{waitUntil:"domcontentloaded",timeout:60000});\nawait page.waitForSelector("canvas",{state:"visible",timeout:30000});
await page.waitForTimeout(6500);

const shots=[
  ["00-entrance.png",0],
  ["01-formation.png",.24],
  ["02-practice.png",.52],
  ["03-systems.png",.78],
  ["04-horizon.png",.97],
];

for(const [name,progress] of shots){
  await page.evaluate((p)=>window.scrollTo({top:(document.documentElement.scrollHeight-innerHeight)*p,behavior:"instant"}),progress);
  await page.waitForTimeout(1800);
  await page.mouse.move(1030,390);
  await page.waitForTimeout(400);
  await page.screenshot({path:"visual-review/"+name,fullPage:false});
}
await browser.close();
console.log("V4 visual review captured.");
